import{_ as r,c as a,o as e,a0 as d}from"./chunks/framework.C1J0Vcxi.js";const g=JSON.parse('{"title":"技术报告-2026-02","description":"","frontmatter":{"title":"技术报告-2026-02","date":"2026-02-28","author":"Oveln"},"headers":[],"relativePath":"技术报告/2026-02-28-技术报告-2026-02.md","filePath":"技术报告/2026-02-28-技术报告-2026-02.md"}'),l={name:"技术报告/2026-02-28-技术报告-2026-02.md"};function o(i,t,s,n,h,p){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="embassy-preempt-rtos-2026年2月技术报告" tabindex="-1">Embassy Preempt RTOS - 2026年2月技术报告 <a class="header-anchor" href="#embassy-preempt-rtos-2026年2月技术报告" aria-label="Permalink to &quot;Embassy Preempt RTOS - 2026年2月技术报告&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>2026年2月，完成了JH7110（VisionFive 2）平台的中断管理、日志系统完善以及性能基准测试。</p><h2 id="二、主要工作内容" tabindex="-1">二、主要工作内容 <a class="header-anchor" href="#二、主要工作内容" aria-label="Permalink to &quot;二、主要工作内容&quot;">​</a></h2><h3 id="_2-1-内存管理优化-第十一周" tabindex="-1">2.1 内存管理优化（第十一周） <a class="header-anchor" href="#_2-1-内存管理优化-第十一周" aria-label="Permalink to &quot;2.1 内存管理优化（第十一周）&quot;">​</a></h3><p><strong>问题诊断</strong></p><ul><li>发现原有内存地址（0x80400000）与OpenSBI/U-Boot存在内存冲突</li><li>导致hart1（运行OpenSBI）报错崩溃</li><li>定位到VisionFive 2启动流程的内存布局冲突问题</li></ul><p><strong>解决方案</strong></p><ul><li>分析JH7110启动阶段的内存分配</li><li>调整内存布局到合法地址空间</li><li>在各系统间设立专用内存区域，防止相互踩踏</li></ul><h3 id="_2-2-uart日志驱动实现-第十二周" tabindex="-1">2.2 UART日志驱动实现（第十二周） <a class="header-anchor" href="#_2-2-uart日志驱动实现-第十二周" aria-label="Permalink to &quot;2.2 UART日志驱动实现（第十二周）&quot;">​</a></h3><p><strong>实现目标</strong></p><ul><li>为<code>embassy-preempt-log</code>添加除defmt-rtt外的第二个输出后端</li><li>实现运行时日志的串口输出</li><li>为后续系统测试提供日志支持</li></ul><p><strong>技术实现</strong></p><p>实现了基于uart16550的串口驱动，为JH7110平台配置了双串口方案：</p><ul><li><strong>UART0</strong> (0x10010000): 用于embassy_preempt的日志输出</li><li><strong>UART1</strong> (0x10011000): 保留给U-Boot及后续Linux系统使用</li></ul><p>这种配置使得embassy_preempt的运行日志可以独立输出，不会与U-Boot/Linux的console输出混在一起，便于调试和问题追踪。</p><p>通过添加<code>log-uart</code> feature flag，可以灵活选择日志输出后端（defmt-rtt或UART）。</p><h3 id="_2-3-中断与时钟优化-第十三周" tabindex="-1">2.3 中断与时钟优化（第十三周） <a class="header-anchor" href="#_2-3-中断与时钟优化-第十三周" aria-label="Permalink to &quot;2.3 中断与时钟优化（第十三周）&quot;">​</a></h3><p><strong>问题</strong></p><ol><li>riscv_rt的中断管理与embassy_preempt上下文切换不兼容</li><li>缺少机器时钟中断处理逻辑</li></ol><p><strong>解决方案</strong></p><ol><li><p><strong>中断管理初始化</strong></p><ul><li>在platform初始化时启用RISC-V机器中断</li><li>设置中断向量表入口地址</li></ul></li><li><p><strong>零栈开销ecall处理</strong></p><ul><li>使用汇编实现，覆盖riscv_rt中断管理策略</li><li>避免上下文切换时的栈冲突问题</li></ul></li><li><p><strong>时钟中断处理</strong></p><ul><li>实现完整的机器时钟中断处理函数</li><li>支持多路alarm定时器触发</li><li>在中断中检查并触发超时的alarm回调</li></ul></li></ol><h3 id="_2-4-性能基准测试-第十三周" tabindex="-1">2.4 性能基准测试（第十三周） <a class="header-anchor" href="#_2-4-性能基准测试-第十三周" aria-label="Permalink to &quot;2.4 性能基准测试（第十三周）&quot;">​</a></h3><p><strong>测试目的</strong> 量化RTOS实时性能关键指标：</p><ul><li>任务创建延迟</li><li>任务切换延迟</li><li>中断响应延迟</li></ul><p><strong>测试环境</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>规格</th></tr></thead><tbody><tr><td>硬件平台</td><td>StarFive JH7110 (VisionFive2)</td></tr><tr><td>CPU</td><td>RISC-V U74 @ 1 GHz</td></tr><tr><td>定时器</td><td>CLINT mtime @ 4 MHz</td></tr><tr><td>测量方法</td><td>CPU 指令计数</td></tr></tbody></table><h2 id="三、性能测试结果" tabindex="-1">三、性能测试结果 <a class="header-anchor" href="#三、性能测试结果" aria-label="Permalink to &quot;三、性能测试结果&quot;">​</a></h2><h3 id="_3-1-核心性能指标" tabindex="-1">3.1 核心性能指标 <a class="header-anchor" href="#_3-1-核心性能指标" aria-label="Permalink to &quot;3.1 核心性能指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>CPU循环</th><th>执行时间</th><th>平均延迟</th></tr></thead><tbody><tr><td><strong>任务创建延迟</strong></td><td>400-500条</td><td>400-500 ns</td><td><strong>457 ns</strong></td></tr><tr><td><strong>中断响应延迟</strong></td><td>400-800条</td><td>400-800 ns</td><td><strong>633 ns</strong></td></tr></tbody></table><h3 id="_3-2-性能对比" tabindex="-1">3.2 性能对比 <a class="header-anchor" href="#_3-2-性能对比" aria-label="Permalink to &quot;3.2 性能对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>RTOS/系统</th><th>平台</th><th>CPU频率</th><th>任务创建延迟</th><th>中断响应延迟</th><th>数据来源</th></tr></thead><tbody><tr><td><strong>Embassy Preempt</strong></td><td>RISC-V JH7110</td><td>1 GHz</td><td><strong>457 ns</strong></td><td><strong>633 ns</strong></td><td>实际测试</td></tr><tr><td>Embassy Preempt</td><td>ARM STM32F401RE</td><td>84 MHz</td><td>10.13 μs</td><td>-</td><td>实际测试</td></tr><tr><td>FreeRTOS</td><td>ARM Cortex-M3</td><td>72 MHz</td><td>~12 μs</td><td>-</td><td>文档</td></tr><tr><td>FreeRTOS</td><td>RISC-V HiFive1</td><td>320 MHz</td><td>~1.8 μs</td><td>-</td><td>SiFive</td></tr><tr><td>Zephyr</td><td>ARM Cortex-M</td><td>64 MHz</td><td>~8 μs</td><td>-</td><td>文档</td></tr><tr><td>Linux PREEMPT_RT</td><td>x86_64</td><td>3 GHz</td><td>-</td><td>7-50 μs</td><td>文档</td></tr></tbody></table><h3 id="_3-3-测量方法" tabindex="-1">3.3 测量方法 <a class="header-anchor" href="#_3-3-测量方法" aria-label="Permalink to &quot;3.3 测量方法&quot;">​</a></h3><p><strong>原理</strong>: CPU循环计数 → 时间转换 <strong>公式</strong>: <code>执行时间 = CPU循环次数 / CPU频率 × 10^9</code></p><h2 id="四、技术成果" tabindex="-1">四、技术成果 <a class="header-anchor" href="#四、技术成果" aria-label="Permalink to &quot;四、技术成果&quot;">​</a></h2><ol><li><strong>内存稳定性</strong>: 解决了与固件的内存冲突，系统可稳定启动运行</li><li><strong>调试能力</strong>: 实现双串口UART日志输出，支持运行时系统状态监控</li><li><strong>中断系统</strong>: 完善时钟中断处理，支持定时器和调度器功能</li><li><strong>性能数据</strong>: 获得权威的实时性能基准数据</li></ol><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to &quot;六、总结&quot;">​</a></h2><p>2月份的工作完成了Embassy Preempt在JH7110平台上的核心功能验证：</p><ul><li>✅ 内存管理稳定</li><li>✅ 日志系统完善</li><li>✅ 中断系统优化</li><li>✅ 性能基准确立</li></ul>',39)])])}const b=r(l,[["render",o]]);export{g as __pageData,b as default};
